<script lang="ts">
	import {onMount} from 'svelte';
	import {formatFileSize} from '$lib/student-files';
	import Button from './Button.svelte';
	let {label,file=$bindable(null),files=$bindable([]),multiple=false,accept='',maxSize=10*1024*1024,maxFiles=5,required=false,disabled=false,helper='',error='',progress=null,uploading=false,showFiles=true,onchange}: {label:string;file?:File|null;files?:File[];multiple?:boolean;accept?:string;maxSize?:number;maxFiles?:number;required?:boolean;disabled?:boolean;helper?:string;error?:string;progress?:number|null;uploading?:boolean;showFiles?:boolean;onchange?:(file:File|null,files:File[])=>void}=$props();
	let input:HTMLInputElement,localError=$state(''),dragging=$state(false);
	const chosen=$derived(multiple ? files : file ? [file]:[]),busy=$derived(disabled || progress!==null || uploading);
	const id=$props.id();
	export function browse(){if(!busy)input?.click();}
	function validate(){input.setCustomValidity(localError || (required && !chosen.length ? 'Choose a file for '+label.toLowerCase()+'.':''));if(!input.validity.valid && !localError)localError=input.validationMessage;}
	onMount(()=>{input.addEventListener('ui-validate',validate);return()=>input.removeEventListener('ui-validate',validate);});
	function select(candidates:File[]){
		if(busy)return;localError='';input.setCustomValidity('');
		const types=accept.toLowerCase().split(',').map(t=>t.trim()).filter(Boolean);
		for(const candidate of candidates){const ext='.'+candidate.name.split('.').pop()?.toLowerCase();if(types.length && !types.some(type=>type.startsWith('.') ? type===ext : type.endsWith('/*') ? candidate.type.startsWith(type.slice(0,-1)):candidate.type===type)){localError='Choose a supported file type: '+accept+'.';return;}if(candidate.size>maxSize){localError='Each file must be '+formatFileSize(maxSize)+' or smaller.';return;}}
		const next=multiple ? [...files,...candidates]:candidates.slice(0,1);if(next.length>maxFiles){localError='Choose up to '+maxFiles+' files.';return;}
		files=next;file=next[0]??null;input.value='';onchange?.(file,next);
	}
	function remove(index:number){if(busy)return;const next=chosen.filter((_,i)=>i!==index);files=next;file=next[0]??null;input.value='';localError='';input.setCustomValidity('');onchange?.(file,next);}
</script>
<div class="field file-drop" class:field-invalid={!!(error||localError)}><label for={id}>{label}{#if required}<span class="field-required" aria-hidden="true"> *</span>{/if}</label><div class="drop-zone" class:dragging role="region" aria-label={label+' upload'} ondragover={event=>{event.preventDefault();if(!busy)dragging=true;}} ondragleave={()=>dragging=false} ondrop={event=>{event.preventDefault();dragging=false;select(Array.from(event.dataTransfer?.files??[]));}}><input bind:this={input} {id} type="file" {accept} {multiple} disabled={busy} aria-label={label} required={required&&!chosen.length} aria-invalid={!!(error||localError)} aria-describedby={id+'-help'} onchange={event=>select(Array.from(event.currentTarget.files??[]))} /><i class="fa-solid fa-cloud-arrow-up" aria-hidden="true"></i><p>Drop {multiple?'files':'a file'} here or <span>browse</span></p></div><p id={id+'-help'} class="field-helper">{helper || 'Maximum '+formatFileSize(maxSize)+' per file.'}</p>{#if showFiles}{#each chosen as item,index}<div class="file-chip"><i class="fa-solid fa-file" aria-hidden="true"></i><div><strong>{item.name}</strong><span>{formatFileSize(item.size)}</span></div><Button variant="ghost" size="sm" disabled={busy} ariaLabel={'Remove '+item.name} title={'Remove '+item.name} icon="fa-solid fa-xmark" onclick={()=>remove(index)} /></div>{/each}{/if}{#if progress!==null || uploading}<div class="upload-progress" role="status"><progress value={progress ?? undefined} max="100" aria-label="Upload progress"></progress><span>Uploading… {progress===null ? '' : Math.round(progress)+'%'}</span></div>{/if}{#if error||localError}<p class="field-error" role="alert"><i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i>{error||localError}</p>{/if}</div>
<style>
	.drop-zone {position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--space-2);min-height:120px;padding:var(--space-6);border:1px dashed var(--color-border-strong);border-radius:var(--radius-control);background:var(--color-surface-muted);color:var(--color-text-muted);text-align:center;}
	.drop-zone input {position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;} .drop-zone:focus-within,.drop-zone.dragging {outline:2px solid var(--color-primary);outline-offset:3px;background:var(--color-primary-soft);} .drop-zone>i,.drop-zone p span {color:var(--color-primary);} .drop-zone p span {text-decoration:underline;} .drop-zone:has(input:disabled) {cursor:not-allowed;} .drop-zone input:disabled {cursor:not-allowed;}
	.file-chip {display:flex;align-items:center;gap:var(--space-3);padding:var(--space-2) var(--space-3);border:1px solid var(--color-border);border-radius:var(--radius-control);background:var(--color-primary-soft);min-width:0;} .file-chip>div {flex:1;min-width:0;overflow-wrap:anywhere;} .file-chip strong {display:block;font-size:var(--type-body);font-weight:var(--weight-medium);} .file-chip span {font-size:var(--type-helper);color:var(--color-text-muted);} .upload-progress {display:grid;gap:var(--space-1);font-size:var(--type-helper);color:var(--color-text-muted);} progress {width:100%;accent-color:var(--color-primary);}
</style>
